 (∀ y : ℕ, ∃ F : ℚ → ℚ, PolyBoundM4F4 F m ∧ ∀ x : ℕ, (f x y:ℚ)=F x) ∧
 (∀ x : ℕ, ∃ F : ℚ → ℚ, PolyBoundM4F4 F n ∧ ∀ y : ℕ, (f x y:ℚ)=F y)

